package ui

import (
	"fmt"
	"image"

	"github.com/arfush/yo/ui/assets"
)

func loadAppIcon() (image.Image, error) {
	return assets.AppIcon()
}

// loadSectionIcons loads the header logo variants for every library section.
// The anime section keeps the shared app icon; yomanga and yoranobe have their
// own tiles generated by tools/icongen.
func loadSectionIcons() (map[librarySection]image.Image, error) {
	icons := make(map[librarySection]image.Image, 3)
	anime, err := assets.AppIcon()
	if err != nil {
		return nil, err
	}
	icons[sectionAnime] = anime
	for _, name := range []string{"manga", "ranobe"} {
		img, err := assets.SectionIcon(name)
		if err != nil {
			return nil, fmt.Errorf("load %s icon: %w", name, err)
		}
		if name == "manga" {
			icons[sectionManga] = img
		} else {
			icons[sectionRanobe] = img
		}
	}
	return icons, nil
}
